import{_ as a,C as i,o as r,c as o,j as e,a as l,E as s,a5 as n}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"极简生产力系统（6个月完成6年的工作）","description":"","frontmatter":{"title":"极简生产力系统（6个月完成6年的工作）","originalTitle":"The Minimalist Productivity System (6 Years Of Work In 6 Months)","date":"2024-07-13","originalUrl":"https://thedankoe.com/letters/the-minimalist-productivity-system-6-years-of-work-in-6-months/","minutes":16,"sourceHash":"d5ca490dc903909f583782db0ebda27d74262be4f917900df785181029af954f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-minimalist-productivity-system-6-years-of-work-in-6-months/"}]]},"headers":[],"relativePath":"letters/the-minimalist-productivity-system-6-years-of-work-in-6-months.md","filePath":"letters/the-minimalist-productivity-system-6-years-of-work-in-6-months.md"}'),m={name:"letters/the-minimalist-productivity-system-6-years-of-work-in-6-months.md"};function h(d,p,c,u,f,k){const t=i("ArticleMeta");return r(),o("div",null,[p[0]||(p[0]=e("h1",{id:"极简生产力系统-6个月完成6年的工作",tabindex:"-1"},[l("极简生产力系统（6个月完成6年的工作） "),e("a",{class:"header-anchor",href:"#极简生产力系统-6个月完成6年的工作","aria-label":'Permalink to "极简生产力系统（6个月完成6年的工作）"'},"​")],-1)),s(t),p[1]||(p[1]=n('<p><a href="https://www.youtube.com/embed/QOgR70Y3nBw?si=KNn4WPa77vjGIJTE" target="_blank" rel="noreferrer">观看原文视频</a></p><blockquote><p>人们常说，聪明人工作得更巧妙，而不是更卖力，但富有创造力的人压根就不工作。</p></blockquote><p>我最近在重温我最喜欢的书之一，亚历克斯·索钟-金·庞（Alex Soojung-Kim Pang）的《休息》（Rest）。我内心涌起一股强烈的渴望，想把我学到的东西分享出来，因为我觉得现在的世界极其需要听到这些：</p><p>大多数人之所以难以做好工作，是因为他们工作得太多了。</p><p>他们的大脑始终处于紧绷状态。</p><p>即便油箱见底，依然在路上死撑，因为你觉得自己“必须”到达那个不知所谓的目的地。</p><p>陷入了“做事模式”——这是一种视野狭隘的状态，如果不加干预，它会在你胸口化作一团滚烫的压力，而你甚至很难弄清这压力的源头到底是什么。</p><p>那种心智封闭的<em>感觉</em>。</p><p>正是这种感觉，破坏了你与他人共度的美好时光。让你对生活中与生俱来的丰盈视而不见。让你忘记了拥有一条清晰思路到底是什么体验。</p><p>这些人把过度工作当成一种荣誉勋章。</p><p>他们觉得不能停止工作，因为他们得在自己假想出来的那场赛跑中保持领先。</p><p>我想提出一种不同的工作方式。</p><p>我们所处的世界，已经不再优待那些每周工作40到80小时的人了（我是指把这当成一种重复且永久的生活方式，而不是偶尔为之）。</p><p>世界正在从技术员向创作者转变。</p><p>随着人工智能和自动化技术将入门级工作拉高到资深级水平，技术员要么被取代，要么被迫转型为创作者。</p><p>技术员为了被分配的目标而工作。</p><p>创作者则在培养一种生活方式，这种生活方式会自然而然地通向他们自己选择的目标。</p><blockquote><p>古希腊人视休息为一份伟大的礼物，是文明生活的巅峰。罗马斯多葛派学者认为，没有好的工作，就不可能有好的生活。实际上，几乎每个古代社会都认识到，工作和休息对于美好的生活都是必不可少的：前者提供了生存的手段，后者赋予了生活意义。</p></blockquote><p>如果你想把事情做完，那就去工作。</p><p>如果你想把正确的事情做好，那就去休息。</p><p>休息不是喝着红酒泡泡浴，也不是在海滩上喝玛格丽特。休息是创造性工作的必需品；而正是这种工作，才能真正通向美好生活。</p><p>这听起来有些反直觉，但<em>休息</em>恰恰是你能在6个月内完成6年工作量的方法。</p><p>请保持开放的心态往下看，因为通往那里的路，可能会动摇你所笃信的一切。它可能会摧毁你对未来的那种安全感，因为那份安全感从一开始就是虚幻的。</p><h2 id="破解工作与生活平衡的密码" tabindex="-1">破解工作与生活平衡的密码 <a class="header-anchor" href="#破解工作与生活平衡的密码" aria-label="Permalink to &quot;破解工作与生活平衡的密码&quot;">​</a></h2><p>让我们来做个思想实验。</p><p>你有一个6年的目标：赚到100万美元。</p><p>实现这个目标的低杠杆方式是：</p><ul><li>制定预算，不去买5美元的星巴克咖啡</li><li>努力争取升职加薪，让你的收入增长个10%左右</li><li>计算每个月需要在股市里投入多少钱</li><li>量入为出地生活，并且每天提心吊胆，生怕自己遭遇什么灾难性变故</li></ul><p>现在，接下来的话听起来可能有点极端。</p><p>“你到底是怎么可能在6个月内实现那个6年的目标的？”</p><p>你必须意识到它<em>是</em>可能的。这是第一步。第二步是你要明白，你只是缺乏让它成为现实的知识和技能。你没有去探求那些学校里教不出来的、与你尚未建立的财务目标相关的新知识。第三步是真正理解学习这种量级的东西需要付出什么：那就是经历他妈的海量的失败，直到你承担得起成功的代价。</p><p>我并不是说这样就能在6个月内赚到100万美元。</p><p>我只是为了在这封信里说明一个观点。我敢肯定，如果这能让你在那个时间段内赚到5万或10万美元，你也会很高兴的。</p><ul><li>设定一个宏大的6个月目标，让你的大脑倾向于为了这个目标去学习</li><li>创办一家企业——没错，一家企业——这样你就能对产品、受众和收入拥有完全的控制权</li><li>如此一来，你就被迫去创造性地思考如何实现这个目标</li><li>选择一个无需牺牲你的兴趣就能让你达成该目标的商业模式</li><li>让你的收入年复一年地实现1倍、2倍甚至3倍的增长，而不是拿着六位数的薪水等着那10%的加薪</li></ul><p>如果你是刚开始看这篇时事通讯的新读者，你可能知道，也可能不知道——你根本不需要什么花哨时髦的商业模式来做这件事。</p><p>别再想着去开什么代运营机构或者电商网店了。</p><p>从商业基本原则开始思考——你需要一群受众，以及一种将这群受众变现的方法。</p><p>科技创造了一种美丽的新型媒介（媒介就是你建立、吸引或定位受众的方式），叫作社交媒体，这里聚集了绝大多数的注意力（想赚钱，你就需要注意力）。</p><p>打造个人品牌，或者做一个被目光短浅地贴上“内容创作者”标签的人，就是你将受众吸引到<em>你</em>身边并销售任何你想卖的东西的方式。无论是一项自由职业服务、一款数字产品、一件实体商品……任何你在网上看到人们在卖的东西。</p><p>你本身已经是一家企业了。你拥有可以提供的价值。你只是不知道如何将自己展示在网上的数十亿人面前，并让他们为你的工作买单。互联网是现代生存不可或缺的一部分。</p><p>所以，要运用这种元商业模式来实现那个6个月的目标：</p><ul><li>研究社交媒体，但别误以为它本身就是一种商业模式（没错，想实现增长你就必须研究并实践它，很震惊吧）</li><li>在X或LinkedIn等平台上写内容，积累高质量的受众</li><li>创办一份时事通讯，用更长、更能建立信任的文章（就像这篇一样）来留存和培育这些受众</li><li>如果你愿意，可以把这些文章重新拆解分发到所有其他平台上，就像我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中教的那样</li><li>随着受众的增长，推出数字产品和服务（课程、模板、自由职业服务、辅导等），这能让你在无需投入毕生积蓄去创业的情况下建立现金流（它们的创建成本为零）</li><li>通过系统化的方式，向你的受众推广你有价值的产品或服务</li></ul><p>假设你研究了社交媒体，写了一篇帖子，然后它被一个拥有10万粉丝的账号转发了（因为你拥有做到这一点的<em>技能</em>，是的，<em>技能</em>）。</p><p>现在，那篇帖子获得了几十万的曝光量。</p><p>你顺势推广你的时事通讯（或者你的产品）来培育这批受众。</p><p>你撰写能提供比基础社交媒体内容更多价值的邮件，并推销你的产品。</p><p>既然你拥有了几十万量级的受众流量，而且如果你能坚持6到12个月，如果当发现某些环节失效时你能不断迭代和优化流程，那么我很难相信你无法将哪怕一小部分受众转化为买家。至于这算不算得上一百万美元，算术题就留给你自己去做了。</p><p>可能会有人说：“但不是每个人都能做到这个呀。”</p><p>我想你忘了我在上面说过的：“销售任何你想卖的东西。”</p><p>大多数（即便不是全部）实体企业都在网上做着同样的事情。你现在已经不再靠实体直邮信件和广告牌来营销一家公司了。也许偶尔还会，但我们的目标是高杠杆。</p><p>所以是的，每个人<em>都</em>能做到，前提是他们自己就是那个细分领域。前提是他们不盲从代运营模式和模板化的电商网店。前提是他们深耕自己的兴趣、发挥个性、解决自己的问题，并出售这套解决方案。</p><h3 id="极简工作日哲学" tabindex="-1">极简工作日哲学 <a class="header-anchor" href="#极简工作日哲学" aria-label="Permalink to &quot;极简工作日哲学&quot;">​</a></h3><blockquote><p>和他同时代的一个人说，沃森（Watson）有时间泡妞和打网球是因为他是个天才。但伍尔夫（Woolf）和凯（Kay）让我思考：也许他正是因为腾出了时间去泡妞和打网球，才成为了天才。或许创造性的成就需要旁敲侧击地去获取。</p></blockquote><p>我的4小时工作日哲学在某种程度上已经进化了。</p><p>我不光在用我们刚才讨论的方法建立我的个人业务。</p><p>我还在学习动画，创办一家初创公司，以及做各种其他事情。</p><p>但我工作的方式并没有改变。我觉得自己依然取得了远超常规的成果，而这归功于我选择把注意力投向了<em>什么</em>。</p><p>极简主义不在于拥有的更少，而在于为更重要的事情腾出空间。</p><p>它关乎杠杆。</p><p>它关乎放下那些你<em>以为</em>在让你进步、实则却在拖慢你脚步的事情（比如只看教程却不实际去建一个项目——我不只看教程，我会找一个我想直接实践的教程，边跟着做项目边学技能）。</p><p>它关乎专注于少数能带来超常回报的任务，并将剩下的事情系统化、外包或委派出去。</p><p>但你该如何找到这极少数能让你在创纪录的时间内实现目标的任务呢？</p><p>嗯，你绝对不可能通过走你父母或老师让你走的路来找到它——因为你能直观地看到，那会导致怎样的高压生活方式。</p><p>这是第一步。</p><p>选择合适的载体，让你能控制所有的变量。在工作上，这意味着一门生意。在现代社会，这意味着一门互联网生意。</p><p><strong>第二步</strong>是研究所有视角，并找出其中的规律和原则。如果你研究在线业务，你会发现它们都是在积累受众，然后将受众变现。</p><p><strong>第三步</strong>是理解 <a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day"><strong>Koe定律</strong></a>，该定律指出：杠杆化的工作会不断进化，在为其设定的完成时间内赚取更多收益。</p><p>如果我想作为1个人、在每天工作不超过4小时的情况下赚到100万美元：</p><ol><li>设定的完成时间是4小时，工作时间别超过这个限度（这样你才能揪出那些让你超时工作的问题，并通过系统化、自动化或委派来解决它们）。</li><li>开始用任何你觉得合适的方式在互联网上积累受众。广告、内容等等。我显然会推荐内容，因为它是杠杆率最高的方式。你写一次，随着你越写越好，它能传播给数千甚至数百万的人。</li><li>打造一个最小可行性产品或服务，然后迅速开始销售（一旦你发现问题，比如第一个人没有买单，就开始测试新策略并不断迭代，直到看到成效）。</li><li>学习新技术，掌握新技能，以提升你在这4小时内的效率。</li></ol><p>如果你仅仅只是坚持第一步，贯彻第二步和第三步，并且不忘第四步——你就会拥有一群不断增长的受众，以及一款卖得出去的产品。砰的一声，100万美元（并且还在增长）的收入就来了。</p><p>这就是有试错机制作为后盾的极简主义的力量，也是任何形式进步的本质。</p><h3 id="进步的4个周期" tabindex="-1">进步的4个周期 <a class="header-anchor" href="#进步的4个周期" aria-label="Permalink to &quot;进步的4个周期&quot;">​</a></h3><p>我会长话短说，但我们必须谈谈这个。</p><p>我见过不少知名人士说，你20多岁的时候就该每天爆肝12小时，永不停歇地工作。</p><p>我同意……</p><p>1/4的时间是这样。</p><p>生命是随着章节和阶段徐徐展开的。</p><p>万事万物，我是指所有的事物，都会经历周期。</p><p>既有宏观周期，也有微观周期。宇宙的周期（比如四季），文化的周期（比如节日），你一天的周期（比如上厕所和满足你的性冲动），等等等等。</p><p>这是现实的一条普遍法则。关于无常与熵的法则。</p><p>进步的4个周期是：</p><ul><li><strong>困惑（Perplexity）</strong>——你感到迷茫，不知道接下来的人生该做什么。</li><li><strong>好奇（Curiosity）</strong>——你发现了一丝机会的端倪，并钻进兔子洞一探究竟。</li><li><strong>高强度（Intensity）</strong>——你获得了绝对的清晰感，无法将自己从工作中抽离（每天工作12小时）。</li><li><strong>持续（Consistency）</strong>——你将行之有效的方法系统化，放缓节奏，养成可持续的日常习惯，并把休息变成你创作生活中必不可少的一部分（每天工作4小时）。然后，只要你愿意，你就可以重复这个过程。</li></ul><p>日复一日地做高强度工作，往往花在无脑、低杠杆的任务上，这只会让你的头脑和业务变得臃肿。当你人生的“困惑”阶段本该用“好奇”来解决时，你却试图用“高强度”去硬扛。</p><p>请记住，这些都是意识的元状态。试图强行进入一个新的状态是行不通的。</p><p>当然，去吧，就因为你觉得自己非做不可，就在某个你选择的任务上每天连干12个小时吧。</p><p>我会在我的私信里看到你，和成百上千个觉得自己被劳动价值论欺骗了的人在一起。</p><h2 id="如何在6个月内完成6年的工作" tabindex="-1">如何在6个月内完成6年的工作 <a class="header-anchor" href="#如何在6个月内完成6年的工作" aria-label="Permalink to &quot;如何在6个月内完成6年的工作&quot;">​</a></h2><blockquote><p>但很明显，大脑的创造性工作永远不会停止，即使在休息状态下，大脑也在努力解决问题，检查并抛弃可能的答案，寻找新奇事物。这是一个我们无法真正控制的过程。但通过学会更好地休息，我们可以支持它，让它发挥作用，并在它发现值得我们关注的东西时留心注意。</p></blockquote><p>让我们把学到的东西浓缩成实际的步骤。</p><p><em>但首先，如果你想要休息，你就必须自己去休息，因为这个世界上没人会把休息时间赐给你。</em></p><p>休息能让你的大脑从噪音中过滤出信号。</p><p>有意图的休息是你打破我们大多数人都沉迷其中的“执行模式”那狭隘压力的途径。</p><p>休息，比如散步、举铁、阅读、休闲，或者任何我们可以定义为除了专注工作之外的事情，能够激活默认模式网络（Default Mode Network）。</p><p>简而言之，这意味着你在休息时，你的大脑一样活跃，或者<em>更</em>活跃。</p><p><em>当你休息时，你的大脑在</em> <em><strong>为你</strong></em> <em>工作。</em></p><p>把它想象成“洗澡时的灵光一闪”，或者是你临睡前那些源源不断涌现、可能改变人生的想法。</p><p>如果你总是处于执行模式，那就祝你好运了，看你能不能想出那种<em>能让</em>你在工作中获得更多成果的主意。</p><p>创造性工作者之所以能在如此短的时间内取得巨大进步，其秘密在于他们脑海中涌现的想法，唤醒了他们的意识，<em>去</em>优雅而高质量地完成正确的任务。</p><p>以下是你如何开始撬动这种力量：</p><h3 id="打造你自己的事业" tabindex="-1">打造你自己的事业 <a class="header-anchor" href="#打造你自己的事业" aria-label="Permalink to &quot;打造你自己的事业&quot;">​</a></h3><blockquote><p>致力于你自己的项目有一种特别的感觉。我不会确切地说你更快乐。一个更好的词是兴奋，或者投入。当事情进展顺利时你会很开心，但往往事与愿违…… 那为什么还要做呢？因为对于喜欢这种工作方式的人来说，没有别的事情感觉如此对头。你觉得自己就像回到了自然栖息地的动物，做着你注定要做的事——也许不总是快乐，但清醒且充满生机。——保罗·格雷厄姆 (Paul Graham)</p></blockquote><p>如果你想完成更多撬动杠杆的工作，我不想打击你，但如果你每天只做派给你的项目，那将非常困难。</p><p>所以，如果你已经读到了这里，我很抱歉之前的卖关子。</p><p>也许是时候残忍地审视一下你的处境，别再强求从毫无意义的事情中寻找意义了。也许是时候最终迈出那一步了。那一步你一直想迈出去，因为你知道这是唯一的长远之计，但你却退缩了，因为你可能不得不牺牲一些现在的安逸（而这些安逸最终是可以被更具成就感的东西所取代的）。</p><p>当你打造自己的事业时，你是真的想要工作。只有在经历低谷时，它才感觉像是在“工作”，但这种工作你依然能够忍受。</p><p>当你掌控着项目时，你就能控制创造心流意识状态的变量，而这是实现不可能之事的关键：</p><p>好奇心、激情、目标、自主性、精通。</p><p>我敢说，90%的人公开讨厌他们的工作，9%的人在欺骗自己说他们热爱自己的工作（或者他们根本没有意识到有更好的选择，因为他们从未探索过未知），只有1%的人拥有那少数几份能让他们创造上述条件的工作。</p><p>不是每个人都能拥有这样的工作。</p><p>如果你不知道该打造什么怎么办？</p><p>参考我之前说过的话。</p><p>选择一个元商业模式（meta business model）。一个将商业的两大原则置于首位的模式：建立受众，将受众变现。</p><p>这样，你就可以探索你的兴趣，积累像<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">写作和说服</a>这样具备未来竞争力的二阶技能，并利用电子邮件、平面设计和视频等现代市场需求量大的技能来<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">将这些兴趣变现</a>。</p><p>成为一名“创作者”是一种存在方式，目前它通过互联网来传导，直到能驾驭你人类潜能的最佳方式进化出来为止，它绝不是人们所渲染的那种目光短浅的互联网打工。</p><h3 id="放大你的格局" tabindex="-1">放大你的格局 <a class="header-anchor" href="#放大你的格局" aria-label="Permalink to &quot;放大你的格局&quot;">​</a></h3><p>我们都是在24小时的时钟下运转。</p><p>你可以选择开一家咖啡店，受限于那家店的客流量；或者你也可以选择创立一个咖啡品牌，仅仅受限于互联网上的数十亿人。</p><p>想象一下当地人在你的咖啡店排队的场景。在早高峰期间，每30到60秒就有人刷一次卡，你进账几笔5到20美元的交易。</p><p>现在想象一下，在几年时间里积累了1万、2万或5万人的受众。你推广你的咖啡品牌，这里没有排队的人群。你每一秒都在收到通知。多到你甚至对此感到麻木。</p><p>你选择了杠杆之路，所以一旦系统建立起来，你几乎不需要工作，除非你选择进一步扩张。</p><p>关键在于，实体店老板和网店老板工作的时间一样长，但网店老板有<em>潜力</em>赚取呈指数级增长的收入，并且有权选择少工作。</p><p>你的心智带宽受限于你所打造业务的潜力。</p><p>如果你的头脑局限于一家小小的本地商店，你就会阻碍自己通过新奇事物、探索发现和模式识别来提高大脑多巴胺水平的能力（而这正是不断吸引你回到你正在打造的项目中的燃料）。</p><p>最终，技能获取和成长都会放缓，你会陷入与当初开始讨厌朝九晚五工作时一模一样的境地。</p><p>所以，总结一下，放大格局，并逆向工程推导如何实现它。</p><p>愿景 &gt; 10年目标 &gt; 1年目标 &gt; 月度目标 &gt; 每周目标 &gt; 每日杠杆……</p><p>然后，忘掉那些目标<a href="/letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years">就像我在这里谈到的那样</a>。</p><h3 id="创作者的日常习惯" tabindex="-1">创作者的日常习惯 <a class="header-anchor" href="#创作者的日常习惯" aria-label="Permalink to &quot;创作者的日常习惯&quot;">​</a></h3><p>你需要3个习惯：</p><p>一个用来充实你的大脑。</p><p>一个用来清空你的大脑。</p><p>一个用来使用你的大脑。</p><p>当你消费太多而创造太少时，你会变得焦虑。</p><p>当你创造太多而消费太少时，你会感到无聊，因为你耗尽了用来创造的燃料，所以你只能重复旧的模式，并失去了你所享受的这门手艺的挑战性。</p><p>这就是我所说的“充实、清空、使用”框架。</p><p>这是一个宏观且可持续的日常规律，它允许<em>你</em>在细节上进行尝试。</p><p>尝试在下午用书籍、播客、内容和课程来充实你的大脑。</p><p>尝试在晚上通过写日记、做计划或冥想来清空你的大脑。</p><p>尝试在早上通过写作、深度工作和建设事业来使用你的大脑。</p><p>或者，在每天早上第一件事就把所有这些习惯前置完成。</p><p>又或者，拿出一张纸，开始创建一个系统。把这3个习惯规划到一周里，然后开始执行。如果哪里感觉不顺畅，就改变它并继续尝试，直到顺畅为止。</p><p>你无法在6个月内完成6年的工作，因为你不知道有什么方法可以做到。你不知道有什么方法可以做到，是因为你的脑海里没有涌动着伟大的想法。</p><p>你的大脑有3个功能：消费、连接、创造。</p><p><em>创意流（Ideaflow）。</em></p><p>如果你不把想法联系起来，也不用想法去创造，它们就会停留在你的脑海里，成为你的负担。</p><p>你必须把一个想法<em>付诸实践</em>，才能发现那个只有在付诸实践后才能被发现的新想法。</p><p>没有犁，就不可能构想出拖拉机。</p><p>你可能明白，也可能不明白的是，如果你没有先对那些通向改变人生的想法的“无聊”或“浅薄”想法采取行动，你就无法产生出改变人生的想法。</p><p>你或许应该先集中精力解决摆在你面前的问题——你的健康、金钱和能力——然后再去集中精力解决那些更深刻、更复杂，需要更成熟的心智才能从中受益的问题。</p><h3 id="按杠杆排序的任务优先级" tabindex="-1">按杠杆排序的任务优先级 <a class="header-anchor" href="#按杠杆排序的任务优先级" aria-label="Permalink to &quot;按杠杆排序的任务优先级&quot;">​</a></h3><p>有什么是你可以做的，它既能随着不断的失败而提升有效性，又能让你更接近你的目标？</p><p>现在，只专注于那一件事。</p><p>每天早上第一件事就做它。</p><p>如果你每天早上只有1个小时来打造你自己的事业，那就只做那一件事，并且坦然接受。如果你只有1个小时，你不需要、也不可能工作12个小时。</p><p>还有，别以为成功的企业家一开始就是每天花12个小时在他们的项目上。如果他们像你我一样——他们确实如此——他们也有自己当下的生活，需要用循序渐进的努力去逐步过渡。</p><p>如果你有更多时间，或者已经深入到了打造你自己事业的过程中，把剩下的工作按照杠杆从高到低，或者熵值从低到高进行分层。</p><p>我的工作日是这样的：</p><ul><li>每天第一件事是写作，因为那是我整个业务的燃料。撰写内容、新闻通讯、落地页、推销文案等，这就是商业模式。就是在电脑前打字。</li><li>去散个步，尝试为这一天学点新东西。</li><li>处理 Kortex 的行政工作，开始开放自己进行交流并回复别人的消息。</li></ul><p>除非我正在打造一个新项目，否则真的就这些。</p><p>新项目会需要更多的时间，直到它被系统化，然后我就会回到基准线——大约4小时的工作量。</p><p>在你的工作日中，按优先级排序后垫底的那些任务，可能都是可有可无的，或者很容易自动化或外包的，所以考虑这么做吧。</p><p>感谢你的阅读。</p><p>我们下一封信再聊。</p><p>——丹 (Dan)</p><hr><p><a href="/en/letters/the-minimalist-productivity-system-6-years-of-work-in-6-months">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',166))])}const y=a(m,[["render",h]]);export{g as __pageData,y as default};
